arguments.command:
export PATH="$HOME/.bun/bin:$PATH"; cd ~; 
gbrain recall gbrain-roundtrip-test --json 2>&1 | python3 -c "import sys,json;d=json.load(sys.stdin);print([ (f.get('id'),f.get('fact')) for f in d.get('facts',[])])" ; echo EXIT=${PIPESTATUS[0]}
gbrain recall --grep "conservative mode" --json 2>&1 | python3 -c "import sys,json;d=json.load(sys.stdin);print([ (f.get('id'),f.get('fact')) for f in d.get('facts',[])])"
gbrain recall --query "gbrain install check" --json 2>&1 | python3 -c "import sys,json;d=json.load(sys.stdin);print([ (f.get('id'),f.get('fact')) for f in d.get('facts',[])])"

export PATH="$HOME/.bun/bin:$PATH"; cd ~; 
gbrain recall --grep "conservative mode" --json > /tmp/r1.json; echo EXIT=$?; python3 -c "import json;d=json.load(open('/tmp/r1.json'));print([(f.get('id'),f.get('fact')) for f in d.get('facts',[])])"
gbrain recall --query "gbrain install check" --json > /tmp/r2.json; echo EXIT=$?; python3 -c "import json;d=json.load(open('/tmp/r2.json'));print([(f.get('id'),f.get('fact')) for f in d.get('facts',[])])"

arguments.content:
import { spawn } from 'node:child_process';
const bin = '/harness-state/.bun/bin/gbrain';
const p = spawn(bin, ['serve', '--surface', 'starter', '--advertise', 'verbs'], { env: { ...process.env, GBRAIN_HOME: process.env.HOME }, stdio: ['pipe', 'pipe', 'pipe'] });
let buf = ''; const waiters = new Map(); let id = 0;
p.stdout.on('data', (d) => { buf += d; let i; while ((i = buf.indexOf('\n')) >= 0) { const line = buf.slice(0, i); buf = buf.slice(i + 1); try { const m = JSON.parse(line); if (m.id && waiters.has(m.id)) { waiters.get(m.id)(m); waiters.delete(m.id); } } catch {} } });
p.stderr.on('data', () => {});
const rpc = (method, params) => new Promise((res) => { const myId = ++id; waiters.set(myId, res); p.stdin.write(JSON.stringify({ jsonrpc: '2.0', id: myId, method, params }) + '\n'); });
const text = (r) => (r.result?.content || []).map((c) => c.text).join('\n') || JSON.stringify(r.error || r.result);
const init = await rpc('initialize', { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'install-check', version: '1' } });
console.log('server:', JSON.stringify(init.result?.serverInfo));
p.stdin.write(JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' }) + '\n');
const tools = await rpc('tools/list', {});
console.log('tools:', tools.result.tools.map((t) => t.name).join(', '));
const rem = await rpc('tools/call', { name: 'remember', arguments: { fact: 'MCP round-trip marker: saved through the gbrain MCP server registered in OpenClaw on 2026-11-17.', entity: 'gbrain-roundtrip-test', provenance: 'install-check: MCP stdio round trip', content_origin: 'inferred' } });
console.log('remember:', text(rem).slice(0, 400));
const rec = await rpc('tools/call', { name: 'recall', arguments: { entity: 'gbrain-roundtrip-test' } });
console.log('recall:', text(rec).slice(0, 1200));
p.kill(); process.exit(0);

